	if p := footerFrameConsumerProblems(map[string]bool{"ui/dashboard": true, "ui/x": true}, good, map[command.ViewType]footerSeed{command.ViewDashboard: seedDashboardActivity, command.ViewJobs: seedJobsActivity}); len(p) != 1 {
